package dev.typeahead.core;
import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;
class ShardedDeltaTest {
 Term t(int id,String text,long popularity){return new Term("t"+id,"public",text,"QUERY","tech","en",true,popularity,0);}
 @Test void shardsMatchReferenceWithDedupAndStableTies(){Random random=new Random(727);List<Term> terms=new ArrayList<>();for(int i=0;i<2000;i++)terms.add(t(i,"term "+random.nextInt(700),random.nextInt(100)));TrieIndex reference=new TrieIndex(terms);for(int shards:List.of(1,2,4,8,16)){var index=new ShardedIndex(terms,1,shards,-1);for(String prefix:List.of("","term","term 1","term 69","absent"))for(int k:List.of(1,10,20))assertEquals(reference.prefix(prefix,k),index.prefix(prefix,k));}}
 @Test void deletedPrecomputedResultsRefillAndDuplicatesRevealNextId(){List<Term> terms=new ArrayList<>();for(int i=0;i<100;i++)terms.add(t(i,"prefix "+i,i));terms.add(t(200,"prefix 99",98));Map<String,Term> changes=new HashMap<>();for(int i=75;i<100;i++)changes.put("t"+i,null);var base=new ShardedIndex(terms,1,4,-1);var index=new DeltaIndex(base,changes,1,4,-1);var expected=terms.stream().filter(t->!changes.containsKey(t.id())).toList();assertEquals(new TrieIndex(expected).prefix("prefix",20),index.prefix("prefix",20));assertTrue(index.prefix("prefix 99",20).stream().anyMatch(t->t.id().equals("t200")));}
 @Test void hiddenDuplicateCanBeatCachedKAfterDeletion(){List<Term> terms=new ArrayList<>();terms.add(t(1,"prefix same",100));terms.add(t(2,"prefix same",99));for(int i=3;i<30;i++)terms.add(t(i,"prefix "+i,90-i));Map<String,Term> changed=new HashMap<>();changed.put("t1",null);var updated=new DeltaIndex(new ShardedIndex(terms,1,1,-1),changed,1,1,-1);assertEquals("t2",updated.prefix("prefix",1).getFirst().id());}
 @Test void renameAndPopularityOverlayAndMetadataView(){var original=t(1,"old name",1);var base=new ShardedIndex(List.of(original,t(2,"new other",5)),1,4,-1);Map<String,Term> changed=Map.of(original.id(),t(1,"new name",99));var updated=new DeltaIndex(base,changed,1,4,-1);assertTrue(updated.prefix("old",10).isEmpty());assertEquals("t1",updated.prefix("new",10).getFirst().id());assertEquals("old name",base.prefix("old",10).getFirst().text());Map<String,Term> tombstone=new HashMap<>();tombstone.put("t1",null);var catalog=new OverlayMap(Map.of("t1",original),tombstone);assertEquals(0,catalog.size());assertTrue(catalog.values().isEmpty());assertNull(catalog.get("t1"));}
 @Test void deterministicGlobalMergeIndependentOfArrivalOrder(){var a=List.of(t(1,"same",10),t(2,"second",8));var b=List.of(t(3,"same",20),t(4,"third",8));var expected=List.of(b.getFirst(),a.get(1),b.get(1));assertEquals(expected,ShardedIndex.merge(List.of(a,b),10,TrieIndex.ORDER));assertEquals(expected,ShardedIndex.merge(List.of(b,a),10,TrieIndex.ORDER));}
 @Test void concurrentReadersKeepOldAndNewViews()throws Exception{var base=new ShardedIndex(List.of(t(1,"term one",1)),1,4,-1);var changed=new DeltaIndex(base,Map.of("t1",t(1,"term changed",5)),1,4,-1);try(var executor=Executors.newVirtualThreadPerTaskExecutor()){List<Callable<Void>> tasks=new ArrayList<>();for(int i=0;i<2000;i++)tasks.add(()->{assertEquals("term one",base.prefix("term",10).getFirst().text());assertEquals("term changed",changed.prefix("term",10).getFirst().text());return null;});for(var future:executor.invokeAll(tasks))future.get();}}
}
